// Тикет #6a86f7e7fbd6 «פיתוח: מקור אמת לתוכן הליטורגי» (F-102), проверен 07.10.2026 → עבר QA (session.json: «соответствует F-102 AC1-5»).
// Источник: web-тест .qa/e2e/tests/guided-prayer/gp-07-approved-source-line.spec.ts. Скрины: e7fbd6-1-arvit-k3-approved, e7fbd6-1-tehilim39-approved,
// e7fbd6-1-haetz-approved («מקור: Sefaria.org — … · אושר על ידי בודק QA, 6.10.2026»), e7fbd6-7-arvit-k1-unapproved, e7fbd6-7-mincha-sfarad-unapproved.
// Опора: F-102 AC2 «כל טקסט מסומן בנוסח ובגרסה שאליהם הוא שייך», AC5 (кто утвердил и когда), реджект 05.10 «אחרי אישור טקסט הוא מאבד את הסימון של הגרסה והמקור»;
// S-17 AC7 (נוסח в заголовке). Неутверждённое с «הטקסט עדיין לא אושר…» — не реджект (решение 06.10), фиксируем как есть.
// Утверждения сделаны в админке 05–06.10 и необратимы (session.json test_data). Только чтение.
import { expect } from '@wdio/globals';
import { byText, byTextContains, byTextMatches, expectVisibleText, scrollToText } from '../../helpers/ui.ts';
import { openPrayer, goToPage, goTab } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';
import { ensureNusach, nusachHeader, openTehilimChapter } from '../_lib/app-0710.ts';

// «מקור: <источник> — <издание> … · אושר על ידי <имя>, <дата>»
const APPROVED_LINE = '(?s)מקור: .*אושר על ידי .*\\d{1,2}\\.\\d{1,2}\\.\\d{4}.*';
const UNAPPROVED_LINE = '(?s)הטקסט עדיין לא אושר.*';

async function expectApproved(where: string) {
  await scrollToText('אושר על ידי', 10);
  await expect(byTextMatches(APPROVED_LINE)).toBeDisplayed({ message: `${where}: нет строки «מקור: … · אושר על ידי …»` });
  await expect(byTextContains('הטקסט עדיין לא אושר')).not.toBeDisplayed();
}
async function expectUnapproved(where: string) {
  await scrollToText('הטקסט עדיין לא אושר', 10);
  await expect(byTextMatches(UNAPPROVED_LINE)).toBeDisplayed({ message: `${where}: нет «הטקסט עדיין לא אושר…»` });
  await expect(byTextContains('מקור:')).toBeDisplayed();          // источник виден и у неутверждённого
  await expect(byTextContains('אושר על ידי')).not.toBeDisplayed();
}

describe('מקור אמת: строка источника и утверждения', () => {
  afterEach(async () => { await toHome(); });

  it('ST-01 Утверждённые (ערבית אשכנז קטע 3, תהילים ל״ט, בורא פרי העץ אשכנז): «מקור: … · אושר על ידי …» #6a86f7e7fbd6 @prod-safe', async () => {
    // 1. ערבית (אשכנזי), 3 מתוך 15 — «המעריב ערבים».
    await openPrayer('arvit_ashkenaz', 'ערבית');
    await ensureNusach('אשכנזי');
    await goToPage(3, 15);
    await expectVisibleText('ערבית (אשכנזי)');
    await expectApproved('ערבית אשכנז 3/15');
    await toHome();

    // 2. תהילים ל״ט.
    await openTehilimChapter(39);
    await expectApproved('תהילים ל״ט');
    await toHome();

    // 3. «ברכות» → «בורא פרי העץ», נוסח אשכנז (заголовок «בורא פרי העץ (אשכנזי)»), кнопка «חזרה לברכות».
    await goTab('ברכות');
    await (await scrollToText('בורא פרי העץ')).click();
    await ensureNusach('אשכנזי');
    await expect(nusachHeader('אשכנזי')).toBeDisplayed();
    await expectApproved('בורא פרי העץ אשכנז');
    await expect(byText('חזרה לברכות')).toBeDisplayed();
  });

  it('ST-02 Неутверждённые (ערבית אשכנז קטע 1, מנחה ספרד קטע 1): «הטקסט עדיין לא אושר…» + источник, без «אושר על ידי» #6a86f7e7fbd6 @prod-safe', async () => {
    // 1. ערבית (אשכנזי), 1 מתוך 15.
    await openPrayer('arvit_ashkenaz', 'ערבית');
    await ensureNusach('אשכנזי');
    await goToPage(1, 15);
    await expectUnapproved('ערבית אשכנז 1/15');
    await toHome();

    // 2. מנחה (ספרדי), 1 מתוך 11; в конце вернуть אשכנזי.
    await openPrayer('mincha_ashkenaz', 'מנחה');
    try {
      await ensureNusach('ספרדי');
      await goToPage(1, 11);
      await expectVisibleText('מנחה (ספרדי)');
      await expectUnapproved('מנחה ספרד 1/11');
    } finally {
      await ensureNusach('אשכנזי');
    }
  });
});
